// Generates the runtime-policy projections from the single human-maintained
// source `src/app/runtime-policy.source.json`:
//   1. src/app/runtime-policy.generated.ts      — full + renderer-safe policy
//   2. src/modules/tasks/definitions/job-catalog.generated.ts — job projection
// It also writes the source hash into the generated file so drift verification
// (`verify-runtime-policy.mjs`) can detect edits made outside the source file.
import { createHash } from "node:crypto";
import { readFile, writeFile } from "node:fs/promises";
import { dirname, join, relative } from "node:path";
import { fileURLToPath, pathToFileURL } from "node:url";
import { format } from "prettier";
import { tsImport } from "tsx/esm/api";

const root = join(dirname(fileURLToPath(import.meta.url)), "..");
const sourcePath = join(root, "src/app/runtime-policy.source.json");
const policyOutputPath = join(root, "src/app/runtime-policy.generated.ts");
const jobOutputPath = join(
  root,
  "src/modules/tasks/definitions/job-catalog.generated.ts",
);
const schemaUrl = pathToFileURL(
  join(root, "src/app/runtime-policy.schema.ts"),
).href;

const schema = await tsImport(schemaUrl, import.meta.url);
const rawSource = await readFile(sourcePath, "utf8");
const parsed = schema.RuntimePolicySourceSchema.parse(JSON.parse(rawSource));
const sourceHash = createHash("sha256")
  .update(rawSource)
  .digest("hex")
  .slice(0, 16);

// --- 1. Runtime policy projection -----------------------------------------
// The full policy is server-only (contains executors, timeouts, network
// permission). The renderer-safe projection keeps only display-grade fields;
// it deliberately excludes executor keys, URLs, paths, commands and network
// permission so it can never relax a security boundary from the browser.
const RENDERER_FORBIDDEN =
  /(?:executor|command|path|url|endpoint|script|shell|network|token|secret|key)/i;

function rendererSafeSnapshotPolicies() {
  const result = {};
  for (const [key, policy] of Object.entries(parsed.snapshotPolicies)) {
    result[key] = {
      freshForMinutes: policy.freshForMinutes,
      defaultRefreshMinutes: policy.defaultRefreshMinutes,
      startupPolicy: policy.startupPolicy,
      staleReadable: policy.staleReadable,
      manualRefresh: policy.manualRefresh,
    };
  }
  return result;
}

const rendererSafe = {
  schemaVersion: parsed.schemaVersion,
  snapshotPolicies: rendererSafeSnapshotPolicies(),
  resourceBudgets: parsed.resourceBudgets,
  rollout: parsed.rollout,
};

const policyBody = `// @generated by scripts/generate-runtime-policy.mjs - DO NOT EDIT.
// Source: src/app/runtime-policy.source.json (hash ${sourceHash})

import type {
  RuntimePolicySource,
  SnapshotPolicyKey,
} from "./runtime-policy.schema.ts";

export const RUNTIME_POLICY_SOURCE_HASH = ${JSON.stringify(sourceHash)};

/** Full runtime policy. Server-only: contains executors, timeouts and network permission. */
export const RUNTIME_POLICY: RuntimePolicySource = ${JSON.stringify(parsed, null, 2)};

/** Renderer-safe projection. Never contains executor keys, URLs, paths, commands or network permission. */
export const RENDERER_SAFE_RUNTIME_POLICY: RendererSafeRuntimePolicy = ${JSON.stringify(rendererSafe, null, 2)};

export interface RendererSafeSnapshotPolicy {
  readonly freshForMinutes: number;
  readonly defaultRefreshMinutes: number;
  readonly startupPolicy: "disabled" | "if-stale" | "on-demand-if-stale";
  readonly staleReadable: boolean;
  readonly manualRefresh: boolean;
}

export interface RendererSafeRuntimePolicy {
  readonly schemaVersion: 1;
  readonly snapshotPolicies: Record<SnapshotPolicyKey, RendererSafeSnapshotPolicy>;
  readonly resourceBudgets: {
    readonly maxHeavyCollectors: number;
    readonly maxFileOperations: number;
    readonly maxProjectClassifiers: number;
  };
  readonly rollout: { readonly defaultStage: "legacy" | "shadow" | "compact-read-model" | "snapshot-read" | "unified-refresh" | "new-default" };
}

const FORBIDDEN_SERIALIZED_TOKENS = ["executor", "url", "command", "path", "network", "timeoutMs", "retry"] as const;

export function rendererPolicyIsSafe(policy: RendererSafeRuntimePolicy): boolean {
  const serialized = JSON.stringify(policy).toLowerCase();
  return FORBIDDEN_SERIALIZED_TOKENS.every((token) => !serialized.includes(token));
}
`;

// --- 2. Job catalog projection --------------------------------------------
const jobCatalog = {
  schemaVersion: parsed.scheduledJobs.schemaVersion,
  tasks: parsed.scheduledJobs.tasks,
};
const executorKeys = [
  ...new Set(jobCatalog.tasks.map((task) => task.executorKey)),
];
const jobBody = `// @generated by scripts/generate-runtime-policy.mjs - DO NOT EDIT.
// Source: src/app/runtime-policy.source.json -> scheduledJobs (hash ${sourceHash})
import type { JobCatalog, JobExecutorKey, JobTypeDefinition } from "./contracts.ts";

export const JOB_CATALOG: JobCatalog = ${JSON.stringify(jobCatalog, null, 2)};
export const JOB_DEFINITIONS: readonly JobTypeDefinition[] = JOB_CATALOG.tasks;
export const JOB_EXECUTOR_KEYS: readonly JobExecutorKey[] = ${JSON.stringify(executorKeys)};
export const JOB_CATALOG_VERSION = ${JSON.stringify(sourceHash)};

/** Explicit registry skeleton. P3-04 supplies implementations; no dynamic import is permitted. */
export const JOB_EXECUTOR_REGISTRY: Readonly<Record<JobExecutorKey, null>> = Object.freeze(Object.fromEntries(JOB_EXECUTOR_KEYS.map((key) => [key, null])) as Record<JobExecutorKey, null>);
`;

await writeFile(
  policyOutputPath,
  await format(policyBody, { parser: "typescript" }),
  "utf8",
);
await writeFile(
  jobOutputPath,
  await format(jobBody, { parser: "typescript" }),
  "utf8",
);
console.log(
  `generated ${relative(root, policyOutputPath)} + ${relative(root, jobOutputPath)} (${jobCatalog.tasks.length} jobs, ${sourceHash})`,
);
